from pathlib import Path

# Wird NACH patch_v081.py, patch_v090.py und patch_v091.py ausgefuehrt.
# Version 1.0 integriert die Verpackungsreparatur als ausschliesslich manuell
# aktivierbare Funktion im Fotocrop-Bereich.

main = Path('app/src/main/java/com/kevo/photoboxcamera/MainActivity.kt')
text = main.read_text(encoding='utf-8')

def replace_once(old: str, new: str, label: str):
    global text
    if old not in text:
        raise SystemExit(f'{label} not found; refusing unsafe patch')
    text = text.replace(old, new, 1)

replace_once(
'''    private var lastCapturedJpeg: ByteArray? = null\n    private var lastCropBaseName: String? = null''',
'''    private var lastCapturedJpeg: ByteArray? = null\n    private var lastCropBaseName: String? = null\n    private lateinit var repairToggleButton: Button\n    private lateinit var repairPanel: View\n    private lateinit var repairTearButton: Button\n    private lateinit var tearWidthBar: SeekBar\n    private lateinit var tearBlendBar: SeekBar\n    private lateinit var tearWidthLabel: TextView\n    private lateinit var tearBlendLabel: TextView\n    private lateinit var spotModeButton: Button\n    private lateinit var spotSizeBar: SeekBar\n    private lateinit var spotStrengthBar: SeekBar\n    private lateinit var spotSizeLabel: TextView\n    private lateinit var spotStrengthLabel: TextView\n    private lateinit var repairUndoButton: Button\n    private lateinit var saveRepairedButton: Button\n    private var lastCropBitmap: Bitmap? = null\n    private var repairUndoBitmap: Bitmap? = null\n    private var spotRepairMode = false''',
'repair fields')

