helper_marker = '''    private fun savePngOnTablet(bitmap: Bitmap, name: String) {'''
repair_helpers = '''    private fun setupPackagingRepairUi() {\n        repairPanel.visibility = View.GONE\n        repairUndoButton.isEnabled = false\n        saveRepairedButton.isEnabled = false\n        updateRepairLabels()\n\n        repairToggleButton.setOnClickListener {\n            if (lastCropBitmap == null) {\n                cropStatus.text = "Verpackungsreparatur ist erst nach einem erfolgreichen Fotocrop verfügbar."\n                return@setOnClickListener\n            }\n            val open = repairPanel.visibility != View.VISIBLE\n            repairPanel.visibility = if (open) View.VISIBLE else View.GONE\n            repairToggleButton.text = if (open) "VERPACKUNGSREPARATUR SCHLIESSEN" else "VERPACKUNGSREPARATUR (OPTIONAL)"\n            if (!open) {\n                spotRepairMode = false\n                spotModeButton.text = "PUNKT-REPARATUR AKTIVIEREN"\n            }\n            cropStatus.text = if (open)\n                "Verpackungsreparatur geöffnet. Nur verwenden, wenn die Karte beschädigt ist. Das Modellauto nicht als Punkt-Reparaturziel antippen."\n            else "Verpackungsreparatur geschlossen. Das Fotocrop-Bild bleibt unverändert."\n        }\n\n        tearWidthBar.setOnSeekBarChangeListener(object : SeekBar.OnSeekBarChangeListener {\n            override fun onProgressChanged(seekBar: SeekBar?, progress: Int, fromUser: Boolean) { updateRepairLabels() }\n            override fun onStartTrackingTouch(seekBar: SeekBar?) = Unit\n            override fun onStopTrackingTouch(seekBar: SeekBar?) = Unit\n        })\n        tearBlendBar.setOnSeekBarChangeListener(object : SeekBar.OnSeekBarChangeListener {\n            override fun onProgressChanged(seekBar: SeekBar?, progress: Int, fromUser: Boolean) { updateRepairLabels() }\n            override fun onStartTrackingTouch(seekBar: SeekBar?) = Unit\n            override fun onStopTrackingTouch(seekBar: SeekBar?) = Unit\n        })\n        spotSizeBar.setOnSeekBarChangeListener(object : SeekBar.OnSeekBarChangeListener {\n            override fun onProgressChanged(seekBar: SeekBar?, progress: Int, fromUser: Boolean) { updateRepairLabels() }\n            override fun onStartTrackingTouch(seekBar: SeekBar?) = Unit\n            override fun onStopTrackingTouch(seekBar: SeekBar?) = Unit\n        })\n        spotStrengthBar.setOnSeekBarChangeListener(object : SeekBar.OnSeekBarChangeListener {\n            override fun onProgressChanged(seekBar: SeekBar?, progress: Int, fromUser: Boolean) { updateRepairLabels() }\n            override fun onStartTrackingTouch(seekBar: SeekBar?) = Unit\n            override fun onStopTrackingTouch(seekBar: SeekBar?) = Unit\n        })\n\n        repairTearButton.setOnClickListener { applyTearRepair() }\n        spotModeButton.setOnClickListener {\n            if (lastCropBitmap == null) return@setOnClickListener\n            spotRepairMode = !spotRepairMode\n            spotModeButton.text = if (spotRepairMode) "PUNKT-REPARATUR AKTIV – AUF ABRIEB TIPPEN" else "PUNKT-REPARATUR AKTIVIEREN"\n            cropStatus.text = if (spotRepairMode)\n                "Punkt-Reparatur aktiv. Jetzt ausschließlich auf einen weißen Abriebfleck der Verpackung tippen."\n            else "Punkt-Reparatur deaktiviert."\n        }\n        repairUndoButton.setOnClickListener { undoPackagingRepair() }\n        saveRepairedButton.setOnClickListener { savePackagingRepair() }\n\n        cropPreview.setOnTouchListener { view, event ->\n            if (!spotRepairMode || event.action != MotionEvent.ACTION_UP) return@setOnTouchListener false\n            val bitmap = lastCropBitmap ?: return@setOnTouchListener false\n            val scale = minOf(view.width.toFloat() / bitmap.width, view.height.toFloat() / bitmap.height)\n            if (scale <= 0f) return@setOnTouchListener true\n            val shownW = bitmap.width * scale\n            val shownH = bitmap.height * scale\n            val left = (view.width - shownW) / 2f\n            val top = (view.height - shownH) / 2f\n            val bx = ((event.x - left) / scale).toInt()\n            val by = ((event.y - top) / scale).toInt()\n            if (bx !in 0 until bitmap.width || by !in 0 until bitmap.height) {\n                cropStatus.text = "Bitte direkt auf die sichtbare Verpackung tippen."\n                return@setOnTouchListener true\n            }\n            applySpotRepair(bx, by)\n            true\n        }\n    }\n\n    private fun updateRepairLabels() {\n        tearWidthLabel.text = "Einriss-Reparaturbreite: ${tearWidthBar.progress} px"\n        tearBlendLabel.text = "Einriss-Glättung: ${tearBlendBar.progress} %"\n        spotSizeLabel.text = "Punkt-Reparaturgröße: ${spotSizeBar.progress} px"\n        spotStrengthLabel.text = "Punkt-Reparaturstärke: ${spotStrengthBar.progress} %"\n    }\n\n    private fun setCurrentCropBitmap(bitmap: Bitmap, baseName: String) {\n        val old = lastCropBitmap\n        lastCropBitmap = bitmap\n        lastCropBaseName = baseName\n        cropPreview.setImageBitmap(bitmap)\n        if (old != null && old !== bitmap && old !== repairUndoBitmap) {\n            try { old.recycle() } catch (_: Throwable) {}\n        }\n        try { repairUndoBitmap?.recycle() } catch (_: Throwable) {}\n        repairUndoBitmap = null\n        repairUndoButton.isEnabled = false\n        saveRepairedButton.isEnabled = false\n        spotRepairMode = false\n        spotModeButton.text = "PUNKT-REPARATUR AKTIVIEREN"\n        repairPanel.visibility = View.GONE\n        repairToggleButton.text = "VERPACKUNGSREPARATUR (OPTIONAL)"\n    }\n\n    private fun storeRepairUndo(bitmap: Bitmap) {\n        try { repairUndoBitmap?.recycle() } catch (_: Throwable) {}\n        repairUndoBitmap = bitmap.copy(Bitmap.Config.ARGB_8888, true)\n        repairUndoButton.isEnabled = repairUndoBitmap != null\n    }\n\n    private fun applyTearRepair() {\n        val source = lastCropBitmap ?: run {\n            cropStatus.text = "Noch kein Fotocrop-Bild vorhanden."\n            return\n        }\n        repairTearButton.isEnabled = false\n        val width = tearWidthBar.progress.coerceAtLeast(12)\n        val blend = tearBlendBar.progress\n        cropStatus.text = "Einriss-Reparatur läuft …"\n        thread(name = "PackagingTearRepair", isDaemon = true) {\n            try {\n                val undo = source.copy(Bitmap.Config.ARGB_8888, true)\n                val result = PackagingRepairEngine.repairTear(source, width, blend)\n                runOnUiThread {\n                    try { repairUndoBitmap?.recycle() } catch (_: Throwable) {}\n                    repairUndoBitmap = undo\n                    repairUndoButton.isEnabled = true\n                    replaceRepairBitmap(result.bitmap)\n                    saveRepairedButton.isEnabled = true\n                    cropStatus.text = "${result.message}\\nBearbeitete Verpackungspixel: ${result.changedPixels}\\nNoch nicht gespeichert – bei Gefallen 'REPARIERTES BILD SPEICHERN' drücken."\n                    repairTearButton.isEnabled = true\n                }\n            } catch (t: Throwable) {\n                runOnUiThread {\n                    cropStatus.text = "Einriss-Reparatur fehlgeschlagen: ${t.message ?: t.javaClass.simpleName}"\n                    repairTearButton.isEnabled = true\n                }\n            }\n        }\n    }\n\n    private fun applySpotRepair(x: Int, y: Int) {\n        val source = lastCropBitmap ?: return\n        spotModeButton.isEnabled = false\n        val radius = spotSizeBar.progress.coerceAtLeast(4)\n        val strength = spotStrengthBar.progress.coerceAtLeast(20)\n        cropStatus.text = "Punkt-Reparatur läuft …"\n        thread(name = "PackagingSpotRepair", isDaemon = true) {\n            try {\n                val undo = source.copy(Bitmap.Config.ARGB_8888, true)\n                val result = PackagingRepairEngine.repairSpot(source, x, y, radius, strength)\n                runOnUiThread {\n                    try { repairUndoBitmap?.recycle() } catch (_: Throwable) {}\n                    repairUndoBitmap = undo\n                    repairUndoButton.isEnabled = true\n                    replaceRepairBitmap(result.bitmap)\n                    saveRepairedButton.isEnabled = true\n                    cropStatus.text = "${result.message}\\nBearbeitete Abriebpixel: ${result.changedPixels}\\nPunkt-Reparatur bleibt aktiv für weitere Verpackungsstellen."\n                    spotModeButton.isEnabled = true\n                }\n            } catch (t: Throwable) {\n                runOnUiThread {\n                    cropStatus.text = "Punkt-Reparatur fehlgeschlagen: ${t.message ?: t.javaClass.simpleName}"\n                    spotModeButton.isEnabled = true\n                }\n            }\n        }\n    }\n\n    private fun replaceRepairBitmap(bitmap: Bitmap) {\n        val old = lastCropBitmap\n        lastCropBitmap = bitmap\n        cropPreview.setImageBitmap(bitmap)\n        if (old != null && old !== bitmap && old !== repairUndoBitmap) {\n            try { old.recycle() } catch (_: Throwable) {}\n        }\n    }\n\n    private fun undoPackagingRepair() {\n        val undo = repairUndoBitmap ?: return\n        repairUndoBitmap = null\n        val old = lastCropBitmap\n        lastCropBitmap = undo\n        cropPreview.setImageBitmap(undo)\n        if (old != null && old !== undo) {\n            try { old.recycle() } catch (_: Throwable) {}\n        }\n        repairUndoButton.isEnabled = false\n        saveRepairedButton.isEnabled = true\n        cropStatus.text = "Letzte Verpackungsreparatur rückgängig gemacht."\n    }\n\n    private fun savePackagingRepair() {\n        val bitmap = lastCropBitmap ?: return\n        val base = lastCropBaseName ?: "Collectooow_Photobox_${SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())}"\n        val name = "${base}_REPARIERT.png"\n        try {\n            savePngOnTablet(bitmap, name)\n            cropStatus.text = "Repariertes Verpackungsbild gespeichert:\\n$name\\nPictures/Collectooow Photobox/Fertig"\n        } catch (t: Throwable) {\n            cropStatus.text = "Repariertes Bild konnte nicht gespeichert werden: ${t.message ?: t.javaClass.simpleName}"\n        }\n    }\n\n'''

replace_once(helper_marker, repair_helpers + helper_marker, 'repair helper insertion')

text = text.replace('Photobox 0.9.1 STARTFEHLER', 'Photobox 1.0 STARTFEHLER')
text = text.replace('Collectooow Fotobox 0.9.1', 'Collectooow Fotobox 1.0')
