repair_ui = retry_block + '''\n\n            <Button\n                android:id="@+id/repairToggle"\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:layout_marginTop="8dp"\n                android:text="VERPACKUNGSREPARATUR (OPTIONAL)" />\n\n            <LinearLayout\n                android:id="@+id/repairPanel"\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:orientation="vertical"\n                android:paddingTop="6dp"\n                android:visibility="gone">\n\n                <TextView\n                    android:layout_width="match_parent"\n                    android:layout_height="wrap_content"\n                    android:paddingBottom="6dp"\n                    android:text="Nur bei beschädigten älteren Karten verwenden. Das Modellauto nicht als Punkt-Reparaturziel antippen."\n                    android:textSize="12sp" />\n\n                <TextView\n                    android:id="@+id/tearWidthLabel"\n                    android:layout_width="match_parent"\n                    android:layout_height="wrap_content"\n                    android:text="Einriss-Reparaturbreite: 34 px" />\n\n                <SeekBar\n                    android:id="@+id/tearWidth"\n                    android:layout_width="match_parent"\n                    android:layout_height="wrap_content"\n                    android:min="12"\n                    android:max="320"\n                    android:progress="34" />\n\n                <TextView\n                    android:id="@+id/tearBlendLabel"\n                    android:layout_width="match_parent"\n                    android:layout_height="wrap_content"\n                    android:text="Einriss-Glättung: 65 %" />\n\n                <SeekBar\n                    android:id="@+id/tearBlend"\n                    android:layout_width="match_parent"\n                    android:layout_height="wrap_content"\n                    android:max="100"\n                    android:progress="65" />\n\n                <Button\n                    android:id="@+id/repairTear"\n                    android:layout_width="match_parent"\n                    android:layout_height="wrap_content"\n                    android:text="EINRISS AM AUFHÄNGELOCH REPARIEREN" />\n\n                <TextView\n                    android:id="@+id/spotSizeLabel"\n                    android:layout_width="match_parent"\n                    android:layout_height="wrap_content"\n                    android:paddingTop="8dp"\n                    android:text="Punkt-Reparaturgröße: 18 px" />\n\n                <SeekBar\n                    android:id="@+id/spotSize"\n                    android:layout_width="match_parent"\n                    android:layout_height="wrap_content"\n                    android:min="4"\n                    android:max="90"\n                    android:progress="18" />\n\n                <TextView\n                    android:id="@+id/spotStrengthLabel"\n                    android:layout_width="match_parent"\n                    android:layout_height="wrap_content"\n                    android:text="Punkt-Reparaturstärke: 85 %" />\n\n                <SeekBar\n                    android:id="@+id/spotStrength"\n                    android:layout_width="match_parent"\n                    android:layout_height="wrap_content"\n                    android:min="20"\n                    android:max="100"\n                    android:progress="85" />\n\n                <Button\n                    android:id="@+id/spotMode"\n                    android:layout_width="match_parent"\n                    android:layout_height="wrap_content"\n                    android:text="PUNKT-REPARATUR AKTIVIEREN" />\n\n                <LinearLayout\n                    android:layout_width="match_parent"\n                    android:layout_height="wrap_content"\n                    android:orientation="horizontal">\n\n                    <Button\n                        android:id="@+id/repairUndo"\n                        android:layout_width="0dp"\n                        android:layout_height="wrap_content"\n                        android:layout_weight="1"\n                        android:text="REPARATUR RÜCKGÄNGIG" />\n\n                    <Button\n                        android:id="@+id/saveRepaired"\n                        android:layout_width="0dp"\n                        android:layout_height="wrap_content"\n                        android:layout_weight="1"\n                        android:text="REPARIERTES BILD SPEICHERN" />\n                </LinearLayout>\n            </LinearLayout>'''
if retry_block not in l:
    raise SystemExit('retryCrop layout block not found; refusing unsafe patch')
l = l.replace(retry_block, repair_ui, 1)
l = l.replace('Collectooow! Fotobox 0.9.1', 'Collectooow! Fotobox 1.0')
l = l.replace('0.9.1-Regel:', '1.0-Regel:')
layout.write_text(l, encoding='utf-8')

build = Path('app/build.gradle.kts')
b = build.read_text(encoding='utf-8')
b = b.replace('versionCode = 11', 'versionCode = 12')
b = b.replace('versionName = "0.9.1"', 'versionName = "1.0"')
